// Explicit references so it doesn't matter which HTTP node finished first.
const gh = $('GitHub - ansible/ansible latest').first().json;
const pypi = $('PyPI - ansible package').first().json;
const changelogResp = $('Get changelog excerpt').first().json;
const communityChangelogResp = $('Get community changelog').first().json;

// Neither the ansible-core release body nor the PyPI JSON API embed the
// actual list of changes - both just point at (or omit entirely) a versioned
// changelog file. Pull out just the section for this exact version (between
// its 'vX.Y.Z\n===...' heading and the next one, optionally cut off earlier
// at stopAtRe) so Claude has concrete items to summarize instead of writing
// generic filler.
function extractChangelogSection(resp, version, stopAtRe) {
  if (!resp || resp.message || !resp.content) return '';
  let text;
  try {
    text = Buffer.from(resp.content, 'base64').toString('utf-8');
  } catch (e) {
    return '';
  }
  version = String(version || '').replace(/^v/, '');
  if (!version) return '';
  const headingRe = new RegExp('^v' + version.replace(/\./g, '\\.') + '\\n=+\\n', 'm');
  const startMatch = headingRe.exec(text);
  if (!startMatch) return '';
  let rest = text.slice(startMatch.index + startMatch[0].length);
  const nextHeadingRe = /\nv[0-9]+\.[0-9]+\.[0-9]+\n=+\n/;
  const nextMatch = nextHeadingRe.exec(rest);
  let section = nextMatch ? rest.slice(0, nextMatch.index) : rest;
  if (stopAtRe) {
    const stopMatch = stopAtRe.exec(section);
    if (stopMatch) section = section.slice(0, stopMatch.index);
  }
  return section.trim().slice(0, 4000);
}

const changelogSection = extractChangelogSection(changelogResp, gh.tag_name);
const baseNotes = (gh.body || '').slice(0, 2000);
const notes = changelogSection
  ? baseNotes + '\n\nSpecific changes in this exact version (from the versioned changelog file):\n' + changelogSection
  : baseNotes;

const pypiVersion = (pypi.info || {}).version || null;
// The 'Unchanged Collections' section that follows is a giant per-collection
// list with zero informational value here - cut it before that heading.
const communityChangelogSection = extractChangelogSection(communityChangelogResp, pypiVersion, /\nUnchanged Collections\n-+\n/);

return [
  {
    json: {
      repo_key: 'ansible/ansible',
      source: 'github-release',
      version: gh.tag_name || null,
      release_name: gh.name || gh.tag_name || '',
      notes: notes.slice(0, 6000),
      url: gh.html_url || ('https://github.com/ansible/ansible/releases/tag/' + (gh.tag_name || '')),
    },
  },
  {
    json: {
      repo_key: 'ansible (pypi package)',
      source: 'pypi',
      version: pypiVersion,
      release_name: 'Ansible ' + (pypiVersion || ''),
      notes: (communityChangelogSection
        ? 'What actually changed in this exact community package version (from ansible-community/ansible-build-data):\n' + communityChangelogSection
        : '(no changelog data available for this version - PyPI does not provide one inline, mention that and link to the release)').slice(0, 6000),
      url: 'https://pypi.org/project/ansible/' + (pypiVersion || '') + '/',
    },
  },
];

// State file lives at automation/ansible-release-watch/state.json in the
// blog repo itself - no external DB needed, and every change to it is a
// visible git commit.
const stateResp = $('Get state file').first().json;
let state = {};
let stateSha = null;
if (stateResp && !stateResp.message && stateResp.content) {
  try {
    state = JSON.parse(Buffer.from(stateResp.content, 'base64').toString('utf-8'));
    stateSha = stateResp.sha || null;
  } catch (e) {
    state = {};
  }
}

const current = $('Combine current versions').all().map(i => i.json);
const changed = current.filter(c => c.version && state[c.repo_key] !== c.version);

return changed.map(c => ({ json: { ...c, previous_version: state[c.repo_key] || null, full_state: state, state_sha: stateSha } }));

