// runOnceForEachItem - this runs once PER changed resource (ansible/ansible,
// the pypi community package, and any future collections), not once for the
// whole batch. It used to default to "run once for all items" with $json /
// .first(), which silently collapsed every run down to just the first
// changed item and dropped the rest (e.g. the pypi community package never
// got a PR because ansible/ansible always came first).
const src = $('Determine new versions').item.json;
const response = $json;

function getText(resp) {
  if (!resp) return '';
  // OpenAI-compatible shape (served by claude-bridge, not Anthropic's own API).
  return resp.choices?.[0]?.message?.content || '';
}

const text = getText(response);
if (!text) throw new Error('Claude returned no text: ' + (response?.error?.message || JSON.stringify(response).slice(0, 2000)));
const cleaned = text.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
const jsonStart = cleaned.indexOf('{');
const jsonEnd = cleaned.lastIndexOf('}');

// Claude's JSON often contains real (unescaped) newlines/tabs inside string
// values - e.g. a fenced code block or a paragraph break inside
// body_markdown - which is invalid per strict JSON (control characters must
// be escaped) even though it looks fine to a human. Got longer and more
// likely to hit now that responses carry real multi-paragraph content
// instead of generic filler. Walk the text tracking whether we're inside a
// quoted string (respecting backslash-escapes) and only escape control
// characters found there - untouched outside strings, so real JSON
// structural whitespace is unaffected.
function sanitizeJsonControlChars(str) {
  let inString = false;
  let escapedNext = false;
  let out = '';
  for (let i = 0; i < str.length; i++) {
    const ch = str[i];
    if (!inString) {
      if (ch === '"') inString = true;
      out += ch;
      continue;
    }
    if (escapedNext) {
      out += ch;
      escapedNext = false;
      continue;
    }
    if (ch === '\\') {
      out += ch;
      escapedNext = true;
    } else if (ch === '"') {
      out += ch;
      inString = false;
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (ch === '\t') {
      out += '\\t';
    } else {
      out += ch;
    }
  }
  return out;
}

const draft = JSON.parse(sanitizeJsonControlChars(cleaned.slice(jsonStart, jsonEnd + 1)));

const today = new Date().toISOString().slice(0, 10);
const title = String(draft.title || (src.release_name + ' Released')).trim();
const filename = title.replace(/[\\/:*?"<>|]/g, '') + '.md';

const frontmatter = [
  '---',
  'title: "' + title.replace(/"/g, '\\"') + '"',
  'description: "' + String(draft.description || '').replace(/"/g, '\\"') + '"',
  'author: "Luca Berton"',
  'date: "' + today + '"',
  'category: "' + (['playbooks', 'modules', 'roles', 'inventory', 'troubleshooting', 'cloud', 'cloud-virtualization', 'security', 'networking', 'network', 'containers', 'windows', 'testing', 'basics', 'fundamentals', 'advanced', 'enterprise', 'collections', 'community', 'best-practices', 'getting-started', 'interviews', 'tools', 'news'].includes(draft.category) ? draft.category : 'news') + '"',
  'tags:',
  ...(draft.tags || ['ansible', 'release']).map(t => '  - "' + String(t).replace(/"/g, '\\"') + '"'),
  '---',
].join('\n');

const body = '# ' + title + '\n\n' + String(draft.body_markdown || '');
const fullContent = frontmatter + '\n\n' + body;

const branchSlug = 'ansible-release-' + String(src.repo_key).replace(/[^a-z0-9]+/gi, '-').toLowerCase() + '-' + String(src.version).replace(/[^a-z0-9.]+/gi, '-').toLowerCase();

const newState = { ...src.full_state, [src.repo_key]: src.version };

return { json: {
  filename,
  filePath: 'src/content/tutorials/' + filename,
  fileContentBase64: Buffer.from(fullContent, 'utf-8').toString('base64'),
  branch: branchSlug,
  prTitle: 'New post: ' + title,
  prBody: 'Auto-drafted by the Ansible release watch workflow.\n\nRepo/package: `' + src.repo_key + '`\nNew version: `' + src.version + '` (previous: `' + (src.previous_version || 'none') + '`)\nRelease: ' + src.url + '\n\n**Review before merging:**\n- [ ] fact-check the drafted content against the real release notes\n- [ ] add a thumbnail (falls back to the default one otherwise)\n- [ ] adjust tone/length as needed',
  stateJsonBase64: Buffer.from(JSON.stringify(newState, null, 2), 'utf-8').toString('base64'),
  state_sha: src.state_sha,
} };
